class TokenBucketRateLimiter {
    private final BlockingQueue<Object> tokens;

    TokenBucketRateLimiter(int capacity) {
        tokens = new ArrayBlockingQueue<>(capacity);
    }

    void startRefilling() {
        Thread refiller = new Thread(() -> {
            while (true) {
                tokens.offer(new Object()); // jesli pelne, po prostu pomija
                try { Thread.sleep(100); } catch (InterruptedException e) { break; }
            }
        });
        refiller.setDaemon(true);
        refiller.start();
    }

    boolean tryAcquire(long timeoutMs) throws InterruptedException {
        return tokens.poll(timeoutMs, TimeUnit.MILLISECONDS) != null;
    }
}

