ConcurrentHashMap<Integer, Boolean> forks = new ConcurrentHashMap<>();
for (int i = 0; i < 5; i++) forks.put(i, false); // false = wolny

for (int philosopher = 0; philosopher < 5; philosopher++) {
    int left = philosopher;
    int right = (philosopher + 1) % 5;
    int first = Math.min(left, right); // zawsze podnies MNIEJSZY numer pierwszy
    int second = Math.max(left, right);

    synchronized (forks) {
        if (!forks.get(first) && !forks.get(second)) {
            forks.put(first, true);
            forks.put(second, true);
            System.out.println("Filozof " + philosopher + " je (widelce " + first + "," + second + ")");
            forks.put(first, false);
            forks.put(second, false);
        }
    }
}

class EventBus {
    private final CopyOnWriteArrayList<Consumer<String>> subscribers = new CopyOnWriteArrayList<>();

    void subscribe(Consumer<String> listener) { subscribers.add(listener); }
    void unsubscribe(Consumer<String> listener) { subscribers.remove(listener); }

    void publish(String event) {
        for (Consumer<String> subscriber : subscribers) {
            subscriber.accept(event);
        }
    }
}

