ConcurrentHashMap<String, AtomicInteger> stock = new ConcurrentHashMap<>();
stock.put("laptop", new AtomicInteger(5));

boolean reserve(String product, int qty) {
    AtomicInteger current = stock.get(product);
    if (current == null) return false;
    int[] success = {0};
    current.updateAndGet(value -> {
        if (value >= qty) { success[0] = 1; return value - qty; }
        return value;
    });
    return success[0] == 1;
}

